namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    public static int DiscountCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents * RatePercent(tier) / 100;

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
