namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public static int DiscountCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents * RatePercent(tier) / 100;

    public static int LoyaltyPartCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(DiscountCents(subtotalCents, tier), CapCents);

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null)
    };
}

namespace CheckoutPricing.Domain;

public static class PromoCodePolicy
{
    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    public static int DiscountCents(string? code, int subtotalCents, int loyaltyPartCents)
    {
        if (string.Equals(code, "WELCOME5", StringComparison.OrdinalIgnoreCase))
            return Welcome5Cents;

        if (string.Equals(code, "SUMMER10", StringComparison.OrdinalIgnoreCase))
            return Math.Min((subtotalCents - loyaltyPartCents) / 10, Summer10CapCents);

        return 0;
    }
}

namespace CheckoutPricing.Domain;

public static class ShippingFeePolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCents(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressFee(tier) : StandardFee(payableTotalCents, tier);

    private static int ExpressFee(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardFee(int payableTotalCents, LoyaltyTier tier) =>
        tier is LoyaltyTier.Gold or LoyaltyTier.Platinum || payableTotalCents >= FreeStandardFromCents
            ? 0
            : StandardFeeCents;
}

using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculateLoyaltyDiscountQuery(int SubtotalCents, LoyaltyTier LoyaltyTier, string? PromoCode = null);

public sealed record LoyaltyDiscountQuote(
    int SubtotalCents,
    int DiscountCents,
    int TotalCents,
    LoyaltyTier LoyaltyTier);

public sealed class CalculateLoyaltyDiscount
{
    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query)
    {
        var loyaltyPart = LoyaltyDiscountPolicy.LoyaltyPartCents(query.SubtotalCents, query.LoyaltyTier);
        var promoPart = PromoCodePolicy.DiscountCents(query.PromoCode, query.SubtotalCents, loyaltyPart);
        var discountCents = Math.Min(loyaltyPart + promoPart, query.SubtotalCents);
        return new(query.SubtotalCents, discountCents, query.SubtotalCents - discountCents, query.LoyaltyTier);
    }
}

